import { join } from "path";
import React from "react";
import {
  Document,
  Page,
  Text,
  View,
  Image,
  StyleSheet,
  Font,
} from "@react-pdf/renderer";

// Chemin absolu côté serveur pour Netlify
const fontPath = join(process.cwd(), "font", "brsonomasemibold.ttf");
Font.register({
  family: "BR Sonoma",
  src: fontPath,
});
Font.register({
  family: "Arial",
  fonts: [
    { src: undefined, fontWeight: "normal" }, // Arial natif
  ],
});
Font.register({
  family: "Times",
  fonts: [
    { src: undefined, fontWeight: "normal" }, // Times natif
  ],
});
Font.register({
  family: "Courier",
  fonts: [
    { src: undefined, fontWeight: "normal" }, // Courier natif
  ],
});

// Ce composant adapte le design selon le type et les props IA
export default function DynamicReport(props: {
  title?: string;
  content?: string;
  type?: string;
  props?: any;
  design?: any;
  watermark?: string;
  logo?: string;
  font?: string;
  sections?: Array<{ title: string; content: string }>;
  table?: { headers: string[]; rows: string[][] };
  signature?: string;
}) {
  const {
    title,
    content,
    type,
    props: extra,
    design,
    watermark,
    logo,
    font = "BR Sonoma",
    sections,
    table,
    signature,
  } = props;

  return (
    <Document>
      <Page style={{ ...styles.body, fontFamily: font }}>
        {/* Filigrane */}
        {watermark && (
          <Text
            style={{
              position: "absolute",
              top: "45%",
              left: "10%",
              opacity: 0.12,
              fontSize: 80,
              color: "#1a7f6b",
              transform: "rotate(-30deg)",
              zIndex: 0,
            }}
            render={() => watermark}
            fixed
          />
        )}
        {/* Logo entreprise */}
        {logo && (
          <Image
            src={logo}
            style={{
              width: 120,
              height: 48,
              marginBottom: 18,
              alignSelf: "center",
            }}
          />
        )}
        <Text style={styles.header}>{title || "Document Vyft"}</Text>
        <Text style={styles.type}>{type ? `Type : ${type}` : ""}</Text>
        <View style={styles.section}>
          <Text>{content}</Text>
        </View>
        {/* Sections multiples */}
        {sections &&
          sections.map((sec, idx) => (
            <View key={idx} style={styles.section}>
              <Text style={styles.sectionTitle}>{sec.title}</Text>
              <Text>{sec.content}</Text>
            </View>
          ))}
        {/* Tableau */}
        {table && (
          <View style={styles.table}>
            <View style={styles.tableRow}>
              {table.headers.map((h, i) => (
                <Text key={i} style={styles.tableHeader}>
                  {h}
                </Text>
              ))}
            </View>
            {table.rows.map((row, i) => (
              <View key={i} style={styles.tableRow}>
                {row.map((cell, j) => (
                  <Text key={j} style={styles.tableCell}>
                    {cell}
                  </Text>
                ))}
              </View>
            ))}
          </View>
        )}
        {/* Props dynamiques */}
        {extra &&
          Object.entries(extra).map(([key, value]) => (
            <View key={key} style={styles.section}>
              <Text>
                <b>{key} :</b> {String(value)}
              </Text>
            </View>
          ))}
        {/* Design IA personnalisé */}
        {design && (
          <View style={styles.section}>
            <Text>Design IA personnalisé :</Text>
            <Text>{JSON.stringify(design, null, 2)}</Text>
          </View>
        )}
        {/* Signature */}
        {signature && (
          <View style={styles.section}>
            <Text style={styles.signature}>Signature : {signature}</Text>
          </View>
        )}
      </Page>
    </Document>
  );
}

const styles = StyleSheet.create({
  body: {
    padding: 32,
    fontSize: 13,
    fontFamily: "BR Sonoma",
    position: "relative",
  },
  header: {
    fontSize: 22,
    marginBottom: 12,
    fontWeight: "bold",
    color: "#1a7f6b",
    textAlign: "center",
  },
  type: {
    fontSize: 14,
    marginBottom: 8,
    color: "#444",
    textAlign: "center",
  },
  section: {
    marginBottom: 10,
  },
  sectionTitle: {
    fontSize: 16,
    fontWeight: "bold",
    color: "#444",
    marginBottom: 4,
  },
  table: {
    display: "table",
    width: "auto",
    marginBottom: 12,
  },
  tableRow: {
    flexDirection: "row",
  },
  tableHeader: {
    fontWeight: "bold",
    fontSize: 13,
    color: "#1a7f6b",
    padding: 4,
    borderBottom: "1px solid #e0dbdd",
    minWidth: 60,
  },
  tableCell: {
    fontSize: 13,
    padding: 4,
    minWidth: 60,
  },
  signature: {
    fontSize: 14,
    color: "#222",
    marginTop: 18,
    fontStyle: "italic",
    textAlign: "right",
  },
});